import pandas as pd
import numpy as np
from sklearn.model_selection import train_test_split
import os

# Load data
train_df = pd.read_csv("./input/ru_train.csv")
test_df = pd.read_csv("./input/ru_test_2.csv")
sample_submission = pd.read_csv("./input/ru_sample_submission_2.csv")

# Create id column for test set
test_df["id"] = (
    test_df["sentence_id"].astype(str) + "_" + test_df["token_id"].astype(str)
)

# Create validation split from training data (80/20)
train_data, val_data = train_test_split(train_df, test_size=0.2, random_state=42)

# Build class-aware mapping: (before, class) -> most frequent after
class_mapping = {}
token_class_freq = {}

# Build token-only mapping: before -> most frequent after (across all classes)
token_mapping = {}

for _, row in train_data.iterrows():
    before_val = row["before"]
    after_val = row["after"]
    class_val = row["class"]

    # Track class frequency for each token (for test prediction fallback)
    if before_val not in token_class_freq:
        token_class_freq[before_val] = {}
    if class_val not in token_class_freq[before_val]:
        token_class_freq[before_val][class_val] = 0
    token_class_freq[before_val][class_val] += 1

    # Build class-specific mapping
    key = (before_val, class_val)
    if key not in class_mapping:
        class_mapping[key] = {}
    if after_val not in class_mapping[key]:
        class_mapping[key][after_val] = 0
    class_mapping[key][after_val] += 1

    # Build token-only mapping (across all classes)
    if before_val not in token_mapping:
        token_mapping[before_val] = {}
    if after_val not in token_mapping[before_val]:
        token_mapping[before_val][after_val] = 0
    token_mapping[before_val][after_val] += 1

# Get best after for each (before, class) pair
best_class_mapping = {}
for key in class_mapping:
    best_class_mapping[key] = max(class_mapping[key].items(), key=lambda x: x[1])[0]

# Get best after for each token (across all classes)
best_token_mapping = {}
for token in token_mapping:
    best_token_mapping[token] = max(token_mapping[token].items(), key=lambda x: x[1])[0]


# Function to get best class for a token (for test predictions)
def get_best_class(before_val):
    if before_val in token_class_freq:
        return max(token_class_freq[before_val].items(), key=lambda x: x[1])[0]
    return None


# Validate on hold-out set using class-aware mapping with multi-level fallback
val_predictions = []
val_actuals = []
for _, row in val_data.iterrows():
    before_val = row["before"]
    class_val = row["class"]
    key = (before_val, class_val)

    # Multi-level fallback hierarchy
    if key in best_class_mapping:
        pred = best_class_mapping[key]
    elif before_val in best_token_mapping:
        pred = best_token_mapping[before_val]
    else:
        pred = before_val  # fallback to original

    val_predictions.append(pred)
    val_actuals.append(row["after"])

# Calculate accuracy
accuracy = np.mean(np.array(val_predictions) == np.array(val_actuals))
print(f"Validation Accuracy: {accuracy}")

# Make predictions on test set using class-aware mapping with inferred class and multi-level fallback
test_predictions = []
for _, row in test_df.iterrows():
    before_val = row["before"]
    inferred_class = get_best_class(before_val)

    # Multi-level fallback hierarchy for test predictions
    if inferred_class:
        key = (before_val, inferred_class)
        if key in best_class_mapping:
            pred = best_class_mapping[key]
        elif before_val in best_token_mapping:
            pred = best_token_mapping[before_val]
        else:
            pred = before_val
    elif before_val in best_token_mapping:
        pred = best_token_mapping[before_val]
    else:
        pred = before_val  # fallback to original

    test_predictions.append(pred)

# Create submission file
submission_df = pd.DataFrame({"id": test_df["id"], "after": test_predictions})

# Save submission
os.makedirs("./submission", exist_ok=True)
submission_df.to_csv("./submission/submission.csv", index=False)

print("Submission saved to ./submission/submission.csv")
